def isolated_vertex_expectation(n: int, p: float) -> float:
    """E[isolated vertex count] = n * (1-p)^(n-1)"""
    if n <= 0: return 0.0
    return n * (1 - p) ** (n - 1)

# Example
print(isolated_vertex_expectation(100, 0.05))

import math
def subcritical_component_bound(n: int, k: int, c: float) -> float:
    """P[component >= k] <= n * (c*exp(1-c))^k for G(n,c/n), c<1."""
    if c >= 1 or k <= 0: return 1.0
    return min(1.0, n * (c * math.exp(1 - c)) ** k)

# Example
for k in [5, 10, 20]:
    print(f"k={k}: bound={subcritical_component_bound(1000, k, 0.5):.2e}")

import random, math
from collections import defaultdict

class UF:
    def __init__(s,n): s.p=list(range(n)); s.sz=[1]*n
    def find(s,x):
        while s.p[x]!=x: s.p[x]=s.p[s.p[x]]; x=s.p[x]
        return x
    def union(s,x,y):
        a,b=s.find(x),s.find(y)
        if a!=b: s.p[b]=a; s.sz[a]+=s.sz[b]

def susceptibility(n, p, trials=100):
    vals = []
    for _ in range(trials):
        uf = UF(n)
        for i in range(n):
            for j in range(i+1,n):
                if random.random()<p: uf.union(i,j)
        roots = {}
        for i in range(n): roots[uf.find(i)] = uf.sz[uf.find(i)]
        vals.append(sum(s**2 for s in roots.values())/n)
    mu = sum(vals)/len(vals)
    sd = math.sqrt(sum((x-mu)**2 for x in vals)/(len(vals)-1))
    return mu, 1.96*sd/math.sqrt(len(vals))

random.seed(42)
for c in [0.5, 1.0, 2.0]:
    m, ci = susceptibility(200, c/200, 50)
    print(f"c={c}: chi={m:.1f} +/- {ci:.1f}")
